using Aict.Core;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public sealed class PolicyStrengthTests {
    static readonly DateTimeOffset Now=new(2026,11,3,6,0,0,TimeSpan.Zero);
    static RuleGroup Group()=>new(){Id=Guid.NewGuid(),Name="网站",WebsiteMode=TargetMode.BlockSelected,WebsiteDomains=["example.com"],AlwaysBlock=true};
    static PolicyConfiguration Policy(RuleGroup g)=>new(){ChangeDelay=TimeSpan.FromMinutes(1),Groups=[g]};
    [TestMethod] public void BlacklistExpansionAndExceptionRemovalTighten(){var g=Group() with {WebsiteExceptions=["mail.example.com"]};var p=Policy(g);Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,Policy(g with {WebsiteDomains=["example.com","other.org"],WebsiteExceptions=[]}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,Policy(g with {WebsiteExceptions=["mail.example.com","video.example.com"]}),Now));}
    [TestMethod] public void ParentDomainExpandsButSubdomainNarrowingWaits(){var g=Group() with {WebsiteDomains=["www.example.com"]};Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {WebsiteDomains=["example.com"]}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(Policy(g with {WebsiteDomains=["example.com"]}),Policy(g),Now));}
    [TestMethod] public void AllowlistShrinkAndOutsideRegionsAreComparedCorrectly(){var g=Group() with {WebsiteMode=TargetMode.AllowSelected,WebsiteDomains=["example.com"]};Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {WebsiteDomains=["work.example.com"]}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {WebsiteDomains=["example.com","school.edu"]}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {WebsiteMode=TargetMode.BlockSelected}),Now));}
    [TestMethod] public void WeeklyCrossMidnightContainmentUsesWholeWeek(){var g=Group() with {AlwaysBlock=false,Windows=[new(Weekdays.Monday,23*60,60)]};var expanded=g with {Windows=[new(Weekdays.Monday,22*60,2*60)]};Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(expanded),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(Policy(expanded),Policy(g),Now));}
    [TestMethod] public void QuotaAndDelayCanOnlyDecreaseAndIncreaseRespectively(){var g=Group() with {AlwaysBlock=false,DailyQuota=TimeSpan.FromMinutes(30)};var p=Policy(g);Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,Policy(g with {DailyQuota=TimeSpan.FromMinutes(10)}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,Policy(g with {DailyQuota=TimeSpan.FromMinutes(60)}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,p with {ChangeDelay=TimeSpan.Zero},Now));}
    [TestMethod] public void ChangedCyclePeriodIsNotMistakenForAStrongerCycle(){var g=Group() with {AlwaysBlock=false,Cycle=new(Now,TimeSpan.FromMinutes(2),TimeSpan.FromMinutes(1))};Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {Cycle=g.Cycle! with {BlockFor=TimeSpan.FromMinutes(3)}}),Now));Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {Cycle=new(Now,TimeSpan.FromMinutes(2.5),TimeSpan.FromMinutes(.5))}),Now));}
    [TestMethod] public void TimedExtensionTightensAndShorteningWaits(){var g=Group() with {AlwaysBlock=false,BlockUntilUtc=Now.AddHours(1)};Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {BlockUntilUtc=Now.AddHours(2)}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {BlockUntilUtc=Now.AddMinutes(30)}),Now));}
    [TestMethod] public void RenameAndNewRuleAreImmediateButRemovalAndCalendarChangeWait(){var g=Group();var p=Policy(g);Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,Policy(g with {Name="改名"}),Now));Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(p,p with {Groups=[g,Group()]} ,Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,p with {Groups=[]},Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(p,p with {TimeZoneId="UTC"},Now));}
    [TestMethod] public void AppWhitelistAndBlacklistRespectLocalExceptions(){var g=Group() with {ApplicationMode=TargetMode.AllowSelected,ApplicationIds=["app.a","app.b"],WebsiteMode=TargetMode.None};Assert.IsTrue(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {ApplicationIds=["app.a"]}),Now));Assert.IsFalse(PolicyStrength.IsAtLeastAsRestrictive(Policy(g),Policy(g with {ApplicationExceptions=["app.c"]}),Now));}
}
